// An icon button that opens a menu: the header's ⋯ menu, and the composer's
// + menu, which opens upward because the composer sits at the bottom of the
// pane. It opens on click, moves with the arrow keys, closes on Escape, a
// pick, or a click anywhere else. `buttonRef` lets the owner put focus back
// on the button once something the menu opened is done.
export function ActionMenu({ label, items, buttonRef, icon = 'ellipsis', above = false, disabled = false }: {
  label: string;
  items: MenuItem[];
  buttonRef?: React.RefObject<HTMLButtonElement>;
  icon?: 'ellipsis' | 'plus';
  above?: boolean;
  disabled?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const container = useRef<HTMLDivElement>(null);
  const ownButton = useRef<HTMLButtonElement>(null);
  const button = buttonRef ?? ownButton;

  useEffect(() => {
    if (!open) return;
    container.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus();
    const dismiss = (event: PointerEvent) => {
      if (!container.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open]);

  // A menu cannot stay open on a button that has just been disabled.
  const shown = open && !disabled;

  return <div className={above ? 'chat-actions chat-actions--above' : 'chat-actions'} ref={container} onKeyDown={(event) => {
    if (event.key === 'Escape') { setOpen(false); button.current?.focus(); }
    if (shown && ['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
      event.preventDefault();
      const buttons = Array.from(container.current!.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled)'));
      const index = buttons.indexOf(document.activeElement as HTMLButtonElement);
      buttons[event.key === 'Home' ? 0 : event.key === 'End' ? buttons.length - 1 :
        (index + (event.key === 'ArrowUp' ? -1 : 1) + buttons.length) % buttons.length]?.focus();
    }
  }} onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false); }}>
    <button ref={button} className="chat-icon" aria-label={label} title={label} disabled={disabled}
      aria-haspopup="menu" aria-expanded={shown} onClick={() => setOpen(!open)}>
      <span className={`jp-icon jp-icon-${icon}`} aria-hidden="true" />
    </button>
    {shown && <div className="chat-menu" role="menu" aria-label={label}>
      {items.map((item) => <button key={item.label} role="menuitem" className={item.danger ? 'danger' : undefined}
        disabled={item.disabled} onClick={() => { setOpen(false); item.onSelect(); }}>{item.label}</button>)}
    </div>}
  </div>;
}

// A modal question over the panel: focus starts on its first control and
// stays inside it, and Escape is the same as `onClose` (its Cancel).
export function Dialog({ title, onClose, children }: {
  title: string; onClose: () => void; children: React.ReactNode;

