const ta = document.querySelector('.composer textarea');
const box = document.querySelector('.composer-box');
const setVal = (v) => { Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(ta, v); ta.dispatchEvent(new Event('input', {bubbles:true})); };
const measure = (label) => ({ label, field: ta.getBoundingClientRect().height, box: box.getBoundingClientRect().height, scrolls: ta.scrollHeight > ta.clientHeight, toolbarVisible: document.querySelector('.composer-toolbar').getBoundingClientRect().bottom <= box.getBoundingClientRect().bottom });
const out = [measure('empty')];
const words = 'The bracket cracked at the hook after two days on the wall. Make it stronger without moving the screw holes, keep the outside face smooth, and try to keep the print under three hours. ';
setVal('The bracket cracked at the hook after two days. Make it stronger without moving the screw holes, and keep the print under three hours if you can.');
await new Promise(r => setTimeout(r, 50)); out.push(measure('wrapped paragraph'));
for (let i = 2; i <= 10; i++) { setVal(Array.from({length: i}, (_, k) => 'line ' + k).join('\n')); await new Promise(r => setTimeout(r, 20)); out.push(measure(i + ' lines')); }
setVal(words.repeat(6)); await new Promise(r => setTimeout(r, 50)); out.push(measure('long'));
setVal('a'); await new Promise(r => setTimeout(r, 50)); out.push(measure('back to one'));
const cs = getComputedStyle(box); const tb = document.querySelector('.composer-toolbar');
out.push({ boxPadding: cs.padding, boxGap: cs.gap, radius: cs.borderRadius, shadow: cs.boxShadow, plus: document.querySelector('.composer-choices button').getBoundingClientRect().height, send: document.querySelector('.composer-send').getBoundingClientRect().height, toolbar: tb.getBoundingClientRect().height, fieldFont: getComputedStyle(ta).font, fieldPadding: getComputedStyle(ta).padding });
JSON.stringify(out)

